INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('46b5d07a-de4f-427c-9611-5122628aeaf0', '21feff02-016d-46e2-bb9d-c27495133b1b', '11. óra: Összeszámlálási feladatok megoldása', 'Önálló feladatmegoldás rendszerezett felsorolással és faábrával.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "d4889a14-1fe8-48d0-9bcf-8b32826594d2", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "f94556c9-c3d0-483b-a716-6bc4cd59f3cf", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "dc18f1c2-2938-4a99-a5da-57b6a2056d6e", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "f78a707d-f9bb-4988-b1b1-12f020a36844", "text": "Igaz", "isCorrect": true}, {"id": "2d737c75-8ed9-4598-ac89-3c4673f765b6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0be7c530-c82b-4b09-9211-5ad4560372b1", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "397132b1-9fa3-4a47-a97f-04f4e7e72cf8", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "c6095c91-f068-449a-9b2c-c8507cfb209a", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "13317fe0-7026-4c85-be6d-ebafba35f366", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "4da1fda7-08aa-4db8-b510-8cf596c5d457", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "b8dd31dc-94c4-4ac9-b2eb-66f5cb6a9649", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "caf8c304-7963-49b7-8c38-a513ed06250b", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "46b1aaea-9a60-426e-9002-8868d143746a", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "fa27f20d-7de4-4ac8-ba68-4c69737755d9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f3c61b0f-e00d-419a-80b7-2c693dbd7356", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4a626821-c856-40c4-a044-72bc65893fd6', '21feff02-016d-46e2-bb9d-c27495133b1b', '12. óra: Számonkérés', 'Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "92710704-3a91-4c50-be99-8d6814989b9a", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "81185b27-7a56-4e21-9c5b-64b6bf31ebb1", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "2e53da6e-254d-4966-b8ae-e4d050e31da6", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "9531f8d2-e8f0-42dc-b467-1347b55fb279", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "1cc644e0-b28d-42d7-9498-9e5d3fe7a28e", "text": "|-30|", "isCorrect": true}, {"id": "cf79d16f-3bf1-4b72-a07f-1baabbf6c62f", "text": "|+20|", "isCorrect": false}, {"id": "6561e992-c912-438a-9247-780748fe891a", "text": "Egyenlőek", "isCorrect": false}, {"id": "f5d0972a-d5e6-4aab-88f0-4a5b6d9627b7", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "feb4da44-8ef8-4ce2-819f-d4074c298379", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "02e68ba1-8daf-41ba-92ed-5b286bc52223", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "329cf7d0-a9b3-4114-8276-54ac33062ffd", "text": "Igaz", "isCorrect": true}, {"id": "0def8bd1-15ef-4c01-910f-e60827a2c6b4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "923a28d8-6404-4423-bd66-6db11b8279b6", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "22d1b8ba-89ed-4e5a-8487-39e6baff9073", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "26ae21a9-ea1a-462b-9fbc-98cb3fa2efb9", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "08c13529-eed3-4d58-9019-1b8a00384b84", "text": "Igaz", "isCorrect": true}, {"id": "5e86bc6b-a866-4716-aee8-0bfcebe7d1ad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a967a160-996a-460c-9787-e71ee2fbba82", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('52010dd9-f771-4f02-b346-21838ecac2b7', '21feff02-016d-46e2-bb9d-c27495133b1b', '13. óra: Osztó, többszörös', 'Osztó, többszörös fogalma, osztópárok meghatározása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "fb64de97-8187-4584-9ec5-5df6ff9d21a1", "text": "Mit nevezünk egy ''a'' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "4c09e40a-758d-4201-bad1-a3fa03426a73", "text": "Azt a ''b'' számot, amellyel ''a''-t elosztva a maradék 0", "isCorrect": true}, {"id": "f095d8ab-6ecb-4a0e-b6f4-a824d1675c5b", "text": "Azt a számot, amit ''a''-hoz hozzáadunk", "isCorrect": false}, {"id": "9b6dfcdc-fdf1-43c9-96da-0e602fdb70be", "text": "Azt a számot, ami nagyobb ''a''-nál", "isCorrect": false}, {"id": "57bc8d95-10f6-4c60-bb17-36898db46472", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "cf5f8033-bc0e-449e-978e-d2aad05ab875", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "4d77b964-52f5-44ab-9c95-1f8d707db112", "text": "Igaz", "isCorrect": true}, {"id": "878ae113-e412-4546-9dc7-2336f5e83c27", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "64090b9c-feca-47e8-b46f-7a24fe1c77f2", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0a6b0eac-b976-42aa-8839-fbd63e7df2e3", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "2bf381c1-594f-46f9-adc2-ac97e27288fb", "text": "45", "isCorrect": true}, {"id": "a34cf5c3-f3e4-4439-875c-579e97231b34", "text": "5", "isCorrect": false}, {"id": "613c3436-64f0-425d-a3fd-035d20896b56", "text": "3", "isCorrect": false}, {"id": "b1fbbf54-7253-440f-ab15-12d27683dab7", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "ed5bdc25-58f3-46e7-a186-9d25c25799f4", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "fa546d8d-67d1-4f13-b1a8-6f9541fb0d90", "text": "Igaz", "isCorrect": true}, {"id": "ef9f4f48-b536-4dfd-9df1-8d10cea1b412", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3c1071b8-a2df-410a-9ded-324f5dd99372", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "91736286-a5f8-44f7-9587-837e7b51e10e", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('df933f60-9439-479e-97f2-02df828cbb84', '21feff02-016d-46e2-bb9d-c27495133b1b', '14. óra: Számolás maradékokkal', 'Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "2eb1736c-fd23-4ad5-a0e1-7769c40d5f78", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "37a50a26-8d99-4828-b546-8e2c4b702fef", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "cbd5c8c8-d2b8-4365-bbf6-f81f46cc6330", "text": "Igaz", "isCorrect": true}, {"id": "b81d16c2-e7ef-4b35-b8a7-d18c54fee5a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1578160f-588c-4ddb-ba20-3240879458ed", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "ce3c3196-8bf0-4254-96ba-2b97657c4627", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "3288a023-c04f-447e-9d07-d1e53ab06926", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "233598a5-8590-43ea-b136-181575ebb54c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eb1f987c-cf95-424c-84cc-ad075abe1615", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "c0a1d3f0-01a9-46e3-a380-6d101fb9b4cc", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "0c522420-d6f8-4080-a40b-a5d1914dda2a", "text": "Igaz", "isCorrect": true}, {"id": "906b6eb1-4a8e-4ea1-b13b-1dc95c4d60cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3c065da7-e8eb-4ae0-a676-4cd67ab37f6a", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "d601d780-3aa2-4d76-b7d6-98ef92bac12b", "text": "15", "isCorrect": true}, {"id": "76de888c-c387-40dc-adcd-f53e054270c9", "text": "16", "isCorrect": false}, {"id": "17c585b6-e98a-419d-ba03-f11efdb6f928", "text": "17", "isCorrect": false}, {"id": "9269d510-6974-4e8b-a3eb-932f00d633e5", "text": "19", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('960df621-4f61-49b7-ba83-476ff13aad8d', '21feff02-016d-46e2-bb9d-c27495133b1b', '15. óra: Hány osztója van?', 'Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "7069dc47-1177-4301-89ac-b82136e20f86", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "346a572b-6e3a-426f-851b-87e9290b0f18", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "3390eb3e-cb99-4a29-9ad3-73a998f21cca", "text": "Összetett számok", "isCorrect": false}, {"id": "f5e39bbe-08f7-483e-9b56-83ff52c5436f", "text": "Páros számok", "isCorrect": false}, {"id": "1c733718-13c3-4c43-b12f-49bfb1e7696b", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "292751af-e457-4b18-8892-789b92b9f49d", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "be2c389d-a32e-48ac-8f6f-36009a02afc2", "text": "Igaz", "isCorrect": false}, {"id": "83ea9786-0a0e-40ae-a6f6-730fd5f14c79", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "b23d7bdb-4066-461a-a10b-136923c149ec", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "bae86ae3-a1c4-4282-bb6c-af5447e6bbd8", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "92657011-021f-4719-88b1-ccc556f8858d", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "c9d22e03-4d3f-4125-bb7b-4c33c1b89e14", "text": "Igaz", "isCorrect": true}, {"id": "9b368d2e-18d1-4730-aacc-78220d5bd266", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "09a7b32d-b343-4e7b-add1-e5c52f7b29fb", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "96f70c02-6617-44e7-8e2b-4b4d6ad9ba67", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "968977c5-8702-4af4-bc55-fc1ed14e2654", "text": "13", "isCorrect": true}, {"id": "8a56fef0-bc48-4a3b-8f00-80b01c011203", "text": "9", "isCorrect": false}, {"id": "588dcf01-852b-4a25-b47c-3b8f63f20518", "text": "15", "isCorrect": false}, {"id": "163d7d40-3a48-46d9-988d-cf4b9ebc28fa", "text": "21", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4ed92ad3-a8e5-4206-b58b-1d53dcc82282', '21feff02-016d-46e2-bb9d-c27495133b1b', '16. óra: Feladatok az osztók számának meghatározására, számolás maradékokkal', 'Szöveges feladatok az osztókról és maradékokról.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "8cfe80ae-1e3a-44b9-813b-7fce3799c8bb", "text": "Hány osztója van a 9-nek? (1, 3, 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "14d10148-ace8-49ee-ac76-ececc41d6632", "text": "A négyzetszámoknak páratlan számú osztójuk van.", "type": "true-false", "options": [{"id": "63c92041-8ff5-401a-96fd-0131dd029310", "text": "Igaz (pl. 9-nek 3 osztója van: 1, 3, 9)", "isCorrect": true}, {"id": "51e95b68-1364-4527-910a-a16f5f01b555", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "64fff407-359f-472e-9c79-fc09b40a8275", "text": "Ha 25 alma van és 4 gyerek között egyenlően elosztjuk, hány alma marad a kosárban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "8ed27831-1f66-4bb6-afd1-cb9c2275932f", "text": "Hány prímszám van 10 és 20 között? (11, 13, 17, 19)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "8fe4f938-df19-44e5-a98c-b193b23bfe81", "text": "Melyik szám összetett szám az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "3196a665-d780-4547-add5-16d9edb611f5", "text": "27 (osztói: 1,3,9,27)", "isCorrect": true}, {"id": "6ce9c4e4-e7be-4f01-929a-3bec90e7576a", "text": "23", "isCorrect": false}, {"id": "3a904893-ef5a-43d8-8e51-f26b4ca2bffb", "text": "29", "isCorrect": false}, {"id": "3e56cd3d-843b-4594-9a11-0adf41cefa84", "text": "31", "isCorrect": false}], "timeLimit": 15}, {"id": "3b7e18d3-90d3-4d4b-a19d-6e2ab717967d", "text": "Minden páratlan szám prímszám.", "type": "true-false", "options": [{"id": "9ae58a44-0353-4fde-ae69-c3d6e06104fc", "text": "Igaz", "isCorrect": false}, {"id": "d648d4a6-45c7-4a76-925d-e80cf2a8cd44", "text": "Hamis (pl. 9, 15, 21 nem prím)", "isCorrect": true}], "timeLimit": 15}, {"id": "c7af98f8-9460-4ae4-b625-68cd7f69bcb3", "text": "Mennyi a legkisebb kétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
