INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0d792bad-c787-47f7-9f16-911ca7d5cc61', '21feff02-016d-46e2-bb9d-c27495133b1b', '18. óra: Oszthatóság 3-mal és 9-cel', 'A számjegyek összegén alapuló oszthatósági szabályok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "de1a4c01-37b0-4ffc-a1d9-6782cb5094d9", "text": "Mikor osztható egy szám 3-mal?", "type": "multiple-choice", "options": [{"id": "bb837b2e-d50a-4da8-bfc5-54164a35c05b", "text": "Ha a számjegyeinek összege osztható 3-mal", "isCorrect": true}, {"id": "2f86a030-6fc1-477a-9e71-67f2f6a12645", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "c87b187d-d74a-4732-ab89-47fa556151b3", "text": "Ha páratlan", "isCorrect": false}, {"id": "805c5c73-41f9-474e-801a-f7de28e56b7b", "text": "Ha az utolsó számjegye 3, 6 vagy 9", "isCorrect": false}], "timeLimit": 15}, {"id": "d9303e92-d86c-45e0-a8e5-2bd1796318a0", "text": "Mikor osztható egy szám 9-cel?", "type": "multiple-choice", "options": [{"id": "8c81a41f-9ffa-4a2f-8928-216b565588b5", "text": "Ha a számjegyeinek összege osztható 9-cel", "isCorrect": true}, {"id": "dc815f97-e18b-4e68-b722-e4039dcbb4dd", "text": "Ha 9-re végződik", "isCorrect": false}, {"id": "cff63126-30f9-4da6-84cd-3b349e6fce9f", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "eda65614-ad2d-4221-b599-c8ce0ee737c1", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "2a445199-a0cc-4467-a93d-6cafdcc34849", "text": "Mennyi a 243 számjegyeinek összege (2+4+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "2fa96c06-7f09-4d14-a76f-a45253f5023f", "text": "A 243 osztható 3-mal és 9-cel is.", "type": "true-false", "options": [{"id": "0c773d44-4a00-46a9-a241-ec85b33881ab", "text": "Igaz", "isCorrect": true}, {"id": "3c82f1b3-969e-4d7a-9b6f-7338f35d344c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "178d0e0b-86b7-437