INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a964a664-d0ba-4a7c-a662-691c2e446553', '21feff02-016d-46e2-bb9d-c27495133b1b', '19. óra: Oszthatóság 4-gyel és 100-zal', 'Oszthatósági szabály az utolsó két számjegy alapján.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "4b3df784-2fae-4362-b594-dedf1dec673a", "text": "Mikor osztható egy szám 4-gyel?", "type": "multiple-choice", "options": [{"id": "b5857ff5-8fbd-4efd-aca6-b0c080eb5fb4", "text": "Ha az utolsó két számjegyéből képzett kétjegyű szám osztható 4-gyel (vagy 00)", "isCorrect": true}, {"id": "2db2aba6-6ae8-47f3-97e4-13fbd4fbdd14", "text": "Ha 4-re végződik", "isCorrect": false}, {"id": "d044e947-0be4-40a0-8ad0-28354e8af4a4", "text": "Ha a számjegyek összege 4", "isCorrect": false}, {"id": "843d559f-12b7-48e9-add1-f6c1ae7e0769", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "37019607-091f-43ba-9f2e-19ab41ddfdb9", "text": "Mikor osztható egy szám 100-zal?", "type": "multiple-choice", "options": [{"id": "48f72907-2fd9-482a-a093-fb5b784322e4", "text": "Ha az utolsó két számjegye 00", "isCorrect": true}, {"id": "e11910eb-d741-411b-8af0-855cb945c3d4", "text": "Ha 100-ra végződik", "isCorrect": false}, {"id": "311b3b71-21e1-40b3-8673-15e7863f96a9", "text": "Ha 0-ra végződik", "isCorrect": false}, {"id": "6f2b11f5-638d-4c4d-a5a1-259006ab9865", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "3ce272f2-b67d-43c2-9743-64ef251d1e07", "text": "A 316 osztható 4-gyel (mert 16 osztható 4-gyel).", "type": "true-false", "options": [{"id": "f37716f4-a7eb-4794-8f9f-aa9b1a75b311", "text": "Igaz", "isCorrect": true}, {"id": "84e8a915-34e2-4501-9d18-872492ed4c9e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a42fb147-8482-4eb0-ad9b-d0166c67baec", "text": "A 7500 osztható 100-zal és 4-gyel is.", "type": "true-false", "options": [{"id": "80cbd053-5e90-4884-85cd-97cd2e9d